css:
.print-format {
	font-family: 'Vazirmatn', Tahoma, sans-serif;
	direction: rtl;
	text-align: right;
}

.print-format table {
	direction: rtl;
}

.print-format th, .print-format td {
	text-align: right;
}

.invoice-header {
	display: flex;
	justify-content: space-between;
	margin-bottom: 20px;
}

.company-logo {
	max-width: 150px;
	max-height: 80px;
}

.invoice-title {
	font-size: 24px;
	font-weight: bold;
	color: #1abc9c;
}

.customer-details {
	margin-top: 20px;
	border: 1px solid #ddd;
	padding: 15px;
	border-radius: 5px;
}

.items-table {
	margin-top: 20px;
	width: 100%;
	border-collapse: collapse;
}

.items-table th {
	background-color: #1abc9c;
	color: white;
	padding: 10px;
	border: 1px solid #ddd;
}

.items-table td {
	padding: 8px;
	border: 1px solid #ddd;
}

.totals-section {
	margin-top: 20px;
	float: left;
	width: 300px;
}

.totals-table {
	width: 100%;
	border-collapse: collapse;
}

.totals-table td {
	padding: 8px;
	border: 1px solid #ddd;
}

.totals-table .total-label {
	font-weight: bold;
	background-color: #f5f5f5;
}

.totals-table .grand-total {
	font-size: 16px;
	font-weight: bold;
	background-color: #1abc9c;
	color: white;
}

.footer-section {
	margin-top: 40px;
	clear: both;
	border-top: 2px solid #1abc9c;
	padding-top: 20px;
}

.signature-section {
	display: flex;
	justify-content: space-between;
	margin-top: 30px;
}

.signature-box {
	text-align: center;
	width: 200px;
}

.signature-line {
	border-top: 1px solid #333;
	margin-top: 50px;
	padding-top: 5px;
}

.iranian-info {
	font-size: 12px;
	color: #666;
	margin-top: 10px;
}
